@Service
public class OrderService {
    private final OrderRepository repository;

    public OrderService(OrderRepository repository) {
        this.repository = repository;
    }

    // Modern approach: Optional makes nullability explicit
    public Optional<Order> findOrder(Long orderId) {
        if (orderId == null) {
            return Optional.empty(); // guard at entry point
        }
        return repository.findById(orderId);
    }

    // Safe usage with Optional
    public String getOrderStatus(Long orderId) {
        return findOrder(orderId)
            .map(Order::status)  // only called if Order exists
            .orElse("NOT_FOUND"); // fallback when null
    }
}

public class ArrayIndexExample {
    public static void main(String[] args) {
        String[] products = {"Laptop", "Mouse", "Keyboard"};

        // WRONG: off-by-one error, length is 3 but valid indices are 0-2
        // for (int i = 0; i <= products.length; i++) {
        //     System.out.println(products[i]); // throws exception at i=3
        // }

        // CORRECT: use < instead of <=
        for (int i = 0; i < products.length; i++) {
            System.out.println(products[i]);
        }

        // SAFER: enhanced for-loop eliminates index management
        for (var product : products) {
            System.out.println(product);
        }

        // Validating calculated indices
        int userIndex = getUserInput(); // might be anything
        if (userIndex >= 0 && userIndex < products.length) {
            System.out.println("Selected: " + products[userIndex]);
        } else {
            System.out.println("Invalid selection");
        }
    }

    private static int getUserInput() { return 5; } // example
}

public class CastingExample {
    public static void main(String[] args) {
        // Safe upcasting: always works (String IS-A Object)
        Object obj = "Hello";

        // Unsafe downcasting: compiler allows but runtime may fail
        // Integer num = (Integer) obj; // ClassCastException!

        // SAFE: check type before casting
        if (obj instanceof String str) { // Java 16+ pattern matching
            System.out.println("Length: " + str.length());
        }

        // Generics prevent ClassCastException at compile time
        List<String> names = List.of("Alice", "Bob");
        String first = names.get(0); // no cast needed, type-safe

        // Legacy code without generics (pre-Java 5 style)
        List rawList = new ArrayList();
        rawList.add("text");
        rawList.add(42);
        String item = (String) rawList.get(1); // ClassCastException: Integer can't be cast to String
    }
}

@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @GetMapping("/{orderId}")
    public ResponseEntity<?> getOrder(@PathVariable String orderId) {
        try {
            Long id = Long.parseLong(orderId);
            var order = orderService.findById(id);
            return ResponseEntity.ok(order);
        } catch (NumberFormatException e) {
            // Return 400 Bad Request with helpful message
            return ResponseEntity
                .badRequest()
                .body(Map.of("error", "Order ID must be a valid number"));
        }
    }

    // Alternative: validation before parsing
    public Optional<Integer> parseQuantity(String input) {
        if (input == null || !input.matches("\\d+")) {
            return Optional.empty(); // invalid format
        }
        return Optional.of(Integer.parseInt(input)); // safe now
    }
}

